160		/**
161		 * Adds new interval for SaaS pending jobs cron
162		 *
163		 * @since 3.11.3
164		 *
165		 * @param array[] $schedules An array of non-default cron schedule arrays.
166		 *
167		 * @return array
168		 */
169		public function add_interval( $schedules ) {
170			if ( ! $this->job_processor->is_allowed() ) {
171				return $schedules;
172			}
173	
174			/**
175			 * Filters the cron interval.
176			 *
177			 * @since 3.11
178			 *
179			 * @param int $interval Interval in seconds.
180			 */
181			$interval = rocket_apply_filter_and_deprecated(
182				'rocket_saas_pending_jobs_cron_interval',
183				[ 1 * rocket_get_constant( 'MINUTE_IN_SECONDS', 60 ) ],
184				'3.16',
185				'rocket_rucss_pending_jobs_cron_interval'
186			);
187	
188			$schedules['rocket_saas_pending_jobs'] = [
189				'interval' => $interval,
190				'display'  => esc_html__( 'WP Rocket process pending jobs', 'rocket' ),
191			];
192	
193			$default_interval = 3 * rocket_get_constant( 'DAY_IN_SECONDS', 86400 );
194			/**
195			 * Filters the cron interval for clearing failed jobs.
196			 *
197			 * @param int $interval Interval in seconds.
198			 */
199			$interval = rocket_apply_filter_and_deprecated(
200				'rocket_remove_saas_failed_jobs_cron_interval',
201				[ $default_interval ],
202				'3.16',
203				'rocket_remove_rucss_failed_jobs_cron_interval'
204			);
205			$interval = (bool) $interval ? $interval : $default_interval;
206	
207			$schedules['rocket_remove_saas_failed_jobs'] = [
208				'interval' => $interval,
209				'display'  => esc_html__( 'WP Rocket clear failed jobs', 'rocket' ),
210			];
211	
212			/**
213			 * Filters the cron interval for processing on submit jobs.
214			 *
215			 * @param int $interval Interval in seconds.
216			 */
217			$interval = (int) rocket_apply_filter_and_deprecated(
218				'rocket_remove_saas_on_submit_jobs_cron_interval',
219				[ 1 * rocket_get_constant( 'MINUTE_IN_SECONDS', 60 ) ],
220				'3.16',
221				'rocket_remove_rucss_on_submit_jobs_cron_interval'
222			);
223	
224			$schedules['rocket_saas_on_submit_jobs'] = [
225				'interval' => $interval,
226				'display'  => esc_html__( 'WP Rocket process on submit jobs', 'rocket' ),
227			];
228	
229			return $schedules;
230		}
